     "t": "p",
     "s": "La cabine, en haut, était allumée. Elle était toujours allumée. Élise la fixa, en pensant à la lettre d'Hélène et à un homme qui comptait jusqu'à soixante dans une cuisine, trente-cinq ans plus tôt."
