     "s": "— Mathis dit que tu as deux visages, la nuit, dit-elle doucement. Je lui ai dit d'arrêter ses histoires. Mais il ne ment jamais, tu sais. C'est ça qui m'inquiète. Il n'a jamais menti de sa vie."
